solution.code:
function selectArm(arms, ticket) {
  for (const arm of arms) {
    const keys = Object.keys(arm.match);
    let matched = true;
    for (const key of keys) {
      const requirement = arm.match[key];
      const actual = ticket[key];
      if (requirement !== null && typeof requirement === 'object') {
        if (!(actual > requirement.greaterThan)) {
          matched = false;
        }
      } else if (actual !== requirement) {
        matched = false;
      }
    }
    if (matched) {
      return arm.result;
    }
  }
  return 'unmatched';
}

grading.starterCode:
function selectArm(arms, ticket) {
  // Ignores ordering and returns the last matching arm.
  let found = 'unmatched';
  for (const arm of arms) {
    if (Object.keys(arm.match).length === 0) {
      found = arm.result;
    }
  }
  return found;
}

