This guard is supposed to stop the same customer being added twice, but duplicates keep appearing.

```csharp
public class Customer
{
    public string Email { get; init; } = "";
    public string Name  { get; init; } = "";
}

bool AlreadyPresent(List<Customer> existing, Customer candidate)
{
    foreach (var c in existing)
    {
        if (c == candidate) return true;
    }
    return false;
}
```

`candidate` is constructed fresh from the request body each time. Why does the guard never fire?

solution.code:
function isAssignable(types, sourceName, targetName) {
  if (!types[sourceName] || !types[targetName]) {
    return false;
  }
  const seen = {};
  const queue = [sourceName];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current === targetName) {
      return true;
    }
    if (seen[current]) {
      continue;
    }
    seen[current] = true;
    const entry = types[current];
    if (entry) {
      for (const next of entry.implements) {
        queue.push(next);
      }
    }
  }
  return false;
}

grading.starterCode:
function isAssignable(types, sourceName, targetName) {
  // Structural rule: compares members, which is the TypeScript answer.
  const a = types[sourceName];
  const b = types[targetName];
  if (!a || !b) {
    return false;
  }
  return JSON.stringify(a.members) === JSON.stringify(b.members);
}
